// Partial #84: exact block-Krylov projection on a 9x9 independent-row core.
// This is not block Lanczos diagonalization. The same natural EC matrix feeds
// the block arm and Gaussian control. All source/witness rows are replayed.
use std::fs;use std::time::Instant;
const P:i64=1009;const MOD:i64=1013;const S:usize=8;const L:usize=16;const Q:usize=24;const RHS:usize=25;const N:usize=9;
#[derive(Clone,Copy,Debug,Eq,PartialEq)]enum Pt{O,A(i64,i64)}
fn m(x:i64,n:i64)->i64{x.rem_euclid(n)}
fn inv(x:i64,n:i64)->i64{let(mut a,mut b,mut u,mut v)=(m(x,n),n,1,0);while b!=0{let q=a/b;(a,b)=(b,a-q*b);(u,v)=(v,u-q*v)}assert_eq!(a,1);m(u,n)}
fn neg(p:Pt)->Pt{match p{Pt::O=>p,Pt::A(x,y)=>Pt::A(x,m(-y,P))}}
fn add(a:Pt,b:Pt)->Pt{match(a,b){(Pt::O,t)|(t,Pt::O)=>t,(Pt::A(x,y),Pt::A(u,v))=>{if x==u&&m(y+v,P)==0{return Pt::O}let s=if x==u{m((3*x*x+1)*inv(2*y,P),P)}else{m((v-y)*inv(u-x,P),P)};let xx=m(s*s-x-u,P);Pt::A(xx,m(s*(x-xx)-y,P))}}}
fn mul(mut k:i64,mut p:Pt)->Pt{if k<0{k=-k;p=neg(p)}let mut o=Pt::O;while k>0{if k&1!=0{o=add(o,p)}p=add(p,p);k>>=1}o}
fn base()->Vec<Pt>{let mut v=Vec::new();for x in 0..P{for y in 0..P{if m(y*y-x*x*x-x-14,P)==0{v.push(Pt::A(x,y));break}}if v.len()==S+L{break}}v}
#[derive(Default,Clone,Copy)]struct Ops{adds:u64,muls:u64,invs:u64,matvec:u64,nonzeros:u64}
fn plus(x:i64,y:i64,o:&mut Ops)->i64{o.adds+=1;m(x+y,MOD)}
fn prod(x:i64,y:i64,o:&mut Ops)->i64{o.muls+=1;m(x*y,MOD)}
fn inverse(x:i64,o:&mut Ops)->i64{o.invs+=1;inv(x,MOD)}
#[derive(Clone)]struct Row{v:Vec<i64>,w:Vec<i64>}
fn rank(a:&[Vec<i64>],width:usize,o:&mut Ops)->usize{let mut z=a.to_vec();let mut h=0;for c in 0..width{if let Some(k)=(h..z.len()).find(|&i|z[i][c]!=0){z.swap(h,k);let p=inverse(z[h][c],o);for j in c..width{z[h][j]=prod(z[h][j],p,o)}let pivot=z[h].clone();for i in 0..z.len(){if i!=h{let q=z[i][c];if q!=0{for j in c..width{z[i][j]=plus(z[i][j],-prod(q,pivot[j],o),o)}}}}h+=1}}h}
fn solve(a:&[Vec<i64>],b:&[i64],o:&mut Ops)->Option<Vec<i64>>{let n=b.len();let mut z=vec![vec![0;n+1];n];for i in 0..n{z[i][..n].copy_from_slice(&a[i]);z[i][n]=b[i]}for c in 0..n{let k=(c..n).find(|&i|z[i][c]!=0)?;z.swap(c,k);let p=inverse(z[c][c],o);for j in c..=n{z[c][j]=prod(z[c][j],p,o)}let pivot=z[c].clone();for i in 0..n{if i!=c{let q=z[i][c];if q!=0{for j in c..=n{z[i][j]=plus(z[i][j],-prod(q,pivot[j],o),o)}}}}}Some(z.iter().map(|r|r[n]).collect())}
fn matvec(a:&[Vec<i64>],x:&[i64],o:&mut Ops)->Vec<i64>{o.matvec+=1;let n=x.len();let mut y=vec![0;n];for i in 0..n{for j in 0..n{if a[i][j]!=0{o.nonzeros+=1;y[i]=plus(y[i],prod(a[i][j],x[j],o),o)}}}y}
fn parse()->Vec<Row>{let raw=fs::read_to_string("WS68_NATURAL_PARTIAL.stdout").unwrap();let base=base();let g=base[0];let q=mul(701,g);let mut sources=Vec::new();let mut block=0;let mut seen_first=false;for line in raw.lines(){if !line.starts_with("source "){continue}let t:Vec<&str>=line.split_whitespace().collect();assert_eq!(t.len(),10);let id:usize=t[1][3..].parse().unwrap();if id==0{if seen_first{block+=1;sources.clear()}else{seen_first=true}}if block==0{continue}assert_eq!(block,1);assert_eq!(id,sources.len());let a:i64=t[3][2..].parse().unwrap();let b:i64=t[4][2..].parse().unwrap();let x:i64=t[5][4..].trim_end_matches(',').parse().unwrap();let y:i64=t[6].trim_end_matches(')').parse().unwrap();let r=Pt::A(x,y);let i:usize=t[8][2..].parse().unwrap();let j:usize=t[9][2..].parse().unwrap();assert_eq!(add(base[i],base[j]),r);assert_eq!(add(mul(a,g),mul(b,q)),r);let mut v=vec![0;RHS+1];v[i]+=1;v[j]+=1;v[Q]=m(-b,MOD);v[RHS]=a;sources.push(v)}assert_eq!(sources.len(),152);let mut pivots:Vec<Option<Row>>=vec![None;L];let mut out=Vec::new();let mut op=Ops::default();for (id,src) in sources.iter().enumerate(){let mut w=vec![0;sources.len()];w[id]=1;let mut row=Row{v:src.clone(),w};let mut pivoted=false;for j in 0..L{let col=S+j;if row.v[col]==0{continue}if let Some(p)=&pivots[j]{let z=row.v[col];for k in 0..=RHS{row.v[k]=plus(row.v[k],-prod(z,p.v[k],&mut op),&mut op)}for k in 0..row.w.len(){row.w[k]=plus(row.w[k],-prod(z,p.w[k],&mut op),&mut op)}}else{let z=inverse(row.v[col],&mut op);for v in &mut row.v{*v=prod(*v,z,&mut op)}for v in &mut row.w{*v=prod(*v,z,&mut op)}pivots[j]=Some(row.clone());pivoted=true;break}}if !pivoted{assert!(row.v[S..Q].iter().all(|&v|v==0));out.push(row)}}assert_eq!(out.len(),136);for row in &out{let mut replay=vec![0;RHS+1];for(i,&z)in row.w.iter().enumerate(){if z!=0{for j in 0..=RHS{replay[j]=m(replay[j]+z*sources[i][j],MOD)}}}assert_eq!(replay,row.v);let mut lhs=Pt::O;for j in 0..S+L{if row.v[j]!=0{lhs=add(lhs,mul(row.v[j],base[j]))}}lhs=add(lhs,mul(row.v[Q],q));assert_eq!(lhs,mul(row.v[RHS],g))}println!("source_rows={} complete_rows={} witness_and_group_replays={} large_pivots={} filter_mod_adds={} filter_mod_muls={} filter_mod_invs={}",sources.len(),out.len(),out.len(),pivots.iter().filter(|p|p.is_some()).count(),op.adds,op.muls,op.invs);out}
fn main(){let prep_start=Instant::now();let all=parse();println!("materialize_verify_wall_us={}",prep_start.elapsed().as_micros());let mut rows=Vec::new();let mut anchor=vec![0;RHS+1];anchor[0]=1;anchor[RHS]=1;rows.push(anchor);rows.extend(all.iter().map(|r|r.v.clone()));let mut selected=Vec::new();let mut select_ops=Ops::default();for (id,row) in rows.iter().enumerate(){let v:Vec<i64>=row[..S].iter().copied().chain([row[Q]]).collect();let old=rank(&selected,N,&mut select_ops);let mut next=selected.clone();next.push(v.clone());if rank(&next,N,&mut select_ops)>old{selected.push(v);println!("selected_row={id}")}if selected.len()==N{break}}assert_eq!(selected.len(),N);let chosen:Vec<usize>=raw_selected_ids(&rows,&selected);let rhs:Vec<i64>=chosen.iter().map(|&i|rows[i][RHS]).collect();let nnz:usize=selected.iter().flat_map(|r|r.iter()).filter(|&&v|v!=0).count();println!("core_dimension={N} core_nnz={nnz} selected_source_ids={chosen:?} rank={} selection_mod_adds={} selection_mod_muls={} selection_mod_invs={}",rank(&selected,N,&mut Ops::default()),select_ops.adds,select_ops.muls,select_ops.invs);
 let start=Instant::now();let mut gops=Ops::default();let gx=solve(&selected,&rhs,&mut gops).expect("Gaussian core invertible");let gtime=start.elapsed().as_micros();assert_eq!(gx[S],701);let mut vops=Ops::default();assert_eq!(matvec(&selected,&gx,&mut vops),rhs);for row in &rows{let mut s=0;for j in 0..S{s=m(s+row[j]*gx[j],MOD)}s=m(s+row[Q]*gx[S],MOD);assert_eq!(s,m(row[RHS],MOD))}println!("gaussian solved=true target={} field_adds={} field_muls={} field_invs={} verify_matvec={} verify_nonzeros={} solve_wall_us={gtime}",gx[S],gops.adds,gops.muls,gops.invs,vops.matvec,vops.nonzeros);
 let probes=[(0usize,1usize),(2,3),(4,5)];for (attempt,(p1,p2)) in probes.iter().enumerate(){let st=Instant::now();let mut kop=Ops::default();let mut block=vec![rhs.clone(),vec![0;N],vec![0;N]];block[1][*p1]=1;block[2][*p2]=1;let mut cols=block.clone();for _ in 1..3{block=block.iter().map(|v|matvec(&selected,v,&mut kop)).collect();cols.extend(block.iter().cloned())}let mut km=vec![vec![0;N];N];for j in 0..N{for i in 0..N{km[i][j]=cols[j][i]}}let mut rop=Ops::default();let kr=rank(&km,N,&mut rop);if kr<N{println!("block_attempt={attempt} probes={p1},{p2} status=censored krylov_rank={kr} matvecs={} field_adds={} field_muls={} rank_field_adds={} rank_field_muls={} wall_us={}",kop.matvec,kop.adds,kop.muls,rop.adds,rop.muls,st.elapsed().as_micros());continue}let ak:Vec<Vec<i64>>=cols.iter().map(|v|matvec(&selected,v,&mut kop)).collect();let mut system=vec![vec![0;N];N];for j in 0..N{for i in 0..N{system[i][j]=ak[j][i]}}let mut dense=Ops::default();let coeff=solve(&system,&rhs,&mut dense).expect("AK nonsingular if A,K nonsingular");let mut x=vec![0;N];for j in 0..N{for i in 0..N{x[i]=plus(x[i],prod(coeff[j],cols[j][i],&mut kop),&mut kop)}}let mut check=Ops::default();assert_eq!(matvec(&selected,&x,&mut check),rhs);assert_eq!(x,gx);assert_eq!(x[S],701);for row in &rows{let mut s=0;for j in 0..S{s=m(s+row[j]*x[j],MOD)}s=m(s+row[Q]*x[S],MOD);assert_eq!(s,m(row[RHS],MOD))}println!("block_attempt={attempt} probes={p1},{p2} status=solved krylov_rank={kr} target={} matvecs={} spmv_nonzeros={} projection_rank_adds={} projection_rank_muls={} projection_rank_invs={} dense_adds={} dense_muls={} dense_invs={} block_adds={} block_muls={} verify_matvec={} wall_us={}",x[S],kop.matvec,kop.nonzeros,rop.adds,rop.muls,rop.invs,dense.adds,dense.muls,dense.invs,kop.adds,kop.muls,check.matvec,st.elapsed().as_micros());break}
}
fn raw_selected_ids(rows:&[Vec<i64>],selected:&[Vec<i64>])->Vec<usize>{let mut ids=Vec::new();let mut next=0;for (i,r) in rows.iter().enumerate(){if next==selected.len(){break}let v:Vec<i64>=r[..S].iter().copied().chain([r[Q]]).collect();if v==selected[next]{ids.push(i);next+=1}}assert_eq!(ids.len(),selected.len());ids}
